export const EXERCISE_CATALOG: CatalogExerciseItem[] = RAW_CATALOG;

export const EXERCISE_ID_ALIASES: Record<string, string> = {
  'barbell_bench_press': 'fitbod_barbell_bench_press',
  'incline_dumbbell_press': 'fitbod_incline_dumbbell_bench_press',
  'push_ups': 'fitbod_push_up',
  'chest_dip': 'fitbod_chest_dip',
  'barbell_deadlift': 'fitbod_deadlift',
  'lat_pulldown': 'fitbod_lat_pulldown',
  'pull_up': 'fitbod_pull_up',
  'seated_cable_row': 'fitbod_seated_cable_row',
  'overhead_press': 'fitbod_overhead_press',
  'dumbbell_lateral_raise': 'fitbod_dumbbell_lateral_raise',
  'face_pull': 'fitbod_face_pull',
  'barbell_bicep_curl': 'fitbod_barbell_curl',
  'dumbbell_hammer_curl': 'fitbod_dumbbell_hammer_curl',
  'tricep_rope_pushdown': 'fitbod_tricep_pushdown',
  'skull_crusher': 'fitbod_incline_barbell_skull_crusher',
  'barbell_squat': 'fitbod_barbell_squat',
  'dumbbell_walking_lunges': 'fitbod_dumbbell_walking_lunge',
  'leg_press': 'fitbod_leg_press',
  'romanian_deadlift': 'fitbod_romanian_deadlift',
  'seated_leg_curl': 'fitbod_seated_leg_curl'
};

export function findExerciseInCatalog(idOrName: string): CatalogExerciseItem | undefined {
  if (!idOrName) return undefined;
  const target = idOrName.toLowerCase();
  const aliasedId = EXERCISE_ID_ALIASES[target] || EXERCISE_ID_ALIASES[idOrName];
  if (aliasedId) {
    const found = EXERCISE_CATALOG.find(c => c.id === aliasedId);
    if (found) return found;
  }
  return EXERCISE_CATALOG.find(c => c.id === idOrName || c.id === `fitbod_${idOrName}` || c.name.toLowerCase() === target);
}
